window.MATERIAL_DEEP_DIVES = [
  {id:'cf-organizacao',category:'Direito Constitucional',title:'Organização político-administrativa (arts. 18 a 43)',source:'Material específico enviado',page:219,
   explanation:'A Federação brasileira é formada pela União, Estados, Distrito Federal e Municípios. Todos são autônomos, mas nenhum é soberano isoladamente. Autonomia significa capacidade de auto-organização, autogoverno, autoadministração e autolegislação dentro das competências constitucionais. Território Federal não é ente federativo: integra a União.',
   points:['Brasília é a Capital Federal; o Distrito Federal é o ente federativo onde ela se localiza.','Criação, incorporação, fusão e desmembramento de Municípios dependem de lei estadual, período definido em lei complementar federal, estudo de viabilidade e plebiscito.','É vedado aos entes estabelecer cultos, recusar fé a documentos públicos ou criar distinções entre brasileiros.','Competência privativa da União pode ser delegada aos Estados por lei complementar e somente sobre questões específicas; competência concorrente admite normas gerais da União e suplementação estadual.','O Município legisla sobre interesse local e suplementa a legislação federal e estadual no que couber.'],
   example:'Se a questão disser que os Municípios possuem soberania, está errada. Eles possuem autonomia; soberania pertence à República Federativa do Brasil.',
   bizu:'Antes de responder uma competência, identifique o verbo: legislar costuma apontar para competência legislativa; executar/proteger/cuidar costuma indicar competência administrativa comum.',
   mnemonic:'U-E-DF-M: União, Estados, Distrito Federal e Municípios são os quatro entes. Território fica fora.',
   trap:'Distrito Federal acumula competências estaduais e municipais, mas não pode ser dividido em Municípios.'},
  {id:'cf-nacionalidade',category:'Direito Constitucional',title:'Nacionalidade: brasileiros natos e naturalizados',source:'Material específico enviado',page:219,
   explanation:'Nacionalidade é o vínculo jurídico-político entre pessoa e Estado. A Constituição combina critérios territoriais e de filiação para definir brasileiros natos e prevê formas de naturalização. A regra é a igualdade entre natos e naturalizados; diferenças só podem existir quando a própria Constituição autoriza.',
   points:['Nascido no Brasil é nato, salvo se os pais estrangeiros estiverem a serviço do país deles.','Nascido no exterior pode ser nato quando pai ou mãe brasileira estiver a serviço do Brasil, ou mediante registro/requisitos constitucionais.','Para originário de país de língua portuguesa, a Constituição exige residência ininterrupta de um ano e idoneidade moral, na forma da lei.','Cargos privativos de nato incluem Presidente e Vice, presidências da Câmara e Senado, Ministro do STF, carreira diplomática, oficial das Forças Armadas e Ministro da Defesa.','A perda da nacionalidade obedece às hipóteses constitucionais; não se presume nem decorre de qualquer residência no exterior.'],
   example:'Filho de brasileiros nascido no exterior não é automaticamente estrangeiro: a situação dos pais, o registro e a opção constitucional podem torná-lo brasileiro nato.',
   bizu:'Em questões, separe três perguntas: onde nasceu, a serviço de quem estavam os pais e houve registro/opção?',
   mnemonic:'P-C-S-D-O-M: Presidente/Vice, Câmara, Senado, STF, Diplomata, Oficial e Ministro da Defesa — cargos de nato.',
   trap:'Português equiparado não vira brasileiro naturalizado; recebe direitos em condição de reciprocidade, preservada sua nacionalidade.'},
  {id:'cf-politicos',category:'Direito Constitucional',title:'Direitos políticos, perda e suspensão',source:'Material específico enviado',page:219,
   explanation:'Direitos políticos permitem participar da formação da vontade estatal, sobretudo por voto, candidatura e instrumentos de democracia direta. A Constituição proíbe a cassação; perda e suspensão somente ocorrem nas hipóteses taxativas do art. 15.',
   points:['Sufrágio é universal; voto é direto e secreto, com valor igual para todos.','Plebiscito consulta antes da decisão; referendo consulta depois; iniciativa popular apresenta projeto.','Alistamento e voto são obrigatórios dos 18 aos 70 e facultativos para analfabetos, maiores de 70 e jovens de 16 a 18.','Condenação criminal transitada em julgado suspende direitos políticos enquanto durarem seus efeitos.','A anualidade eleitoral impede aplicar à eleição que ocorra até um ano da vigência a lei que altere o processo eleitoral.'],
   example:'A lei eleitoral entra em vigor na publicação, mas não é aplicada à eleição realizada dentro de um ano: vigência e aplicação não são a mesma coisa.',
   bizu:'Plebiscito vem primeiro; referendo vem depois. Pergunte se o povo autorizou antes ou confirmou depois.',
   mnemonic:'P-A / R-D: Plebiscito Antes, Referendo Depois.',
   trap:'A Constituição veda cassação, mas permite perda ou suspensão nas hipóteses expressamente previstas.'},
  {id:'cf-sociais',category:'Direito Constitucional',title:'Direitos sociais e direitos dos trabalhadores',source:'Material específico enviado',page:219,
   explanation:'Direitos sociais são direitos de segunda dimensão ligados à igualdade material e, em geral, exigem atuação positiva do Estado. O art. 6º enumera direitos sociais; o art. 7º reúne direitos de trabalhadores urbanos e rurais. Reserva do possível não elimina automaticamente o mínimo existencial.',
   points:['Art. 6º: educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança, previdência, proteção à maternidade e infância e assistência aos desamparados.','Direitos trabalhistas buscam melhorar a condição social, como salário mínimo, férias, décimo terceiro, repouso semanal e proteção contra riscos.','Mínimo existencial protege prestações indispensáveis à dignidade; reserva do possível considera disponibilidade real e planejamento estatal.','Direitos sociais são fundamentais e não simples promessas políticas.','A análise concreta deve conciliar dignidade, igualdade, orçamento e proibição de proteção insuficiente.'],
   example:'A alegação genérica de falta de recursos não basta, por si só, para negar prestação essencial; a questão pode exigir demonstração concreta e respeito ao mínimo existencial.',
   bizu:'Decore o art. 6º por blocos: formação e vida digna; trabalho e proteção; amparo social.',
   mnemonic:'EDU MORA e se ALIMENTA; com SAÚDE, TRABALHO, TRANSPORTE e LAZER; SEGURANÇA, PREVIDÊNCIA, MATERNIDADE/INFÂNCIA e ASSISTÊNCIA.',
   trap:'Direitos de segunda dimensão não substituem os de primeira; as dimensões se acumulam e se complementam.'},
  {id:'cf-administracao',category:'Direito Constitucional',title:'Administração Pública e servidores (arts. 37 a 41)',source:'Material específico enviado',page:219,
   explanation:'O art. 37 alcança administração direta e indireta de todos os Poderes e entes. Além dos princípios expressos, disciplina concurso, cargos, remuneração, acumulação, licitação, responsabilidade e improbidade. A legalidade administrativa é mais estrita: o agente atua conforme autorização jurídica.',
   points:['LIMPE: legalidade, impessoalidade, moralidade, publicidade e eficiência.','Concurso vale até dois anos e pode ser prorrogado uma vez por igual período.','Função de confiança é exclusiva de servidor efetivo; cargo em comissão destina-se a direção, chefia e assessoramento.','Acumulação remunerada é excepcional, exige compatibilidade de horários e enquadramento constitucional.','A responsabilidade civil do Estado é objetiva perante o terceiro, com direito de regresso contra o agente em caso de dolo ou culpa.'],
   example:'Duas funções de confiança não podem ser ocupadas por pessoa sem cargo efetivo. Cargo em comissão pode ser de livre nomeação, mas deve atender às finalidades constitucionais.',
   bizu:'Em questão sobre acumulação, verifique três filtros: hipótese permitida, compatibilidade de horários e teto remuneratório.',
   mnemonic:'LIMPE; concurso 2+2; confiança = EFETIVO; comissão = D-C-A (Direção, Chefia, Assessoramento).',
   trap:'Publicidade oficial não pode virar promoção pessoal de autoridade ou servidor.'},
  {id:'cf-legislativo',category:'Direito Constitucional',title:'Poder Legislativo e Congresso Nacional',source:'Material específico enviado',page:219,
   explanation:'O Congresso Nacional é bicameral: Câmara dos Deputados e Senado Federal. A Câmara representa o povo pelo sistema proporcional; o Senado representa Estados e Distrito Federal pelo sistema majoritário. A distinção entre competência do Congresso e competências privativas de cada Casa é recorrente em prova.',
   points:['Legislatura dura quatro anos. Deputado tem mandato de quatro anos; Senador, de oito.','Cada Estado e o DF elegem três Senadores, cada qual com dois suplentes; a renovação ocorre alternadamente por um e dois terços.','Regra geral de deliberação: maioria dos votos, presente a maioria absoluta, salvo disposição constitucional diferente.','Matérias do art. 48 dependem, em regra, de sanção; as dos arts. 49, 51 e 52 dispensam sanção presidencial.','Fiscalização contábil, financeira, orçamentária, operacional e patrimonial é exercida com auxílio do Tribunal de Contas.'],
   example:'Câmara = população; Senado = entes federados. Por isso varia o número de Deputados, mas cada Estado possui três Senadores.',
   bizu:'Ao ver uma competência, marque C, CD ou SF: Congresso, Câmara ou Senado. Isso evita misturar os arts. 49, 51 e 52.',
   mnemonic:'Câmara = P-P (Povo/Proporcional); Senado = E-M-8 (Estados/Majoritário/8 anos).',
   trap:'Tribunal de Contas auxilia o Legislativo, mas não integra o Poder Judiciário.'},
  {id:'cf-executivo',category:'Direito Constitucional',title:'Poder Executivo: Presidente, sucessão e competências',source:'Material específico enviado',page:219,
   explanation:'O Poder Executivo federal é exercido pelo Presidente da República, auxiliado pelos Ministros de Estado. Impedimento gera substituição temporária; vaga gera sucessão definitiva. Competências presidenciais podem ser privativas, algumas delegáveis nos limites constitucionais.',
   points:['Presidente e Vice são eleitos simultaneamente; maioria absoluta exclui votos brancos e nulos.','Vice substitui no impedimento e sucede na vaga. Na falta de ambos, a ordem é Câmara, Senado e STF.','Se ambos os cargos vagarem nos dois primeiros anos, eleição direta em 90 dias; nos dois últimos, eleição indireta pelo Congresso em 30 dias.','Mandato presidencial é de quatro anos, com posse perante o Congresso.','Algumas competências podem ser delegadas a Ministros, PGR ou AGU apenas quando a Constituição permitir.'],
   example:'Viagem temporária ou doença é impedimento e chama substituto; renúncia ou morte abre vaga e chama sucessor.',
   bizu:'Leia o caso procurando duas palavras: temporário = substituição; definitivo = sucessão.',
   mnemonic:'C-S-S: Câmara, Senado, Supremo — ordem após Presidente e Vice.',
   trap:'A eleição do Vice está vinculada à chapa do Presidente; não existe votação presidencial separada para Vice.'},
  {id:'cf-judiciario',category:'Direito Constitucional',title:'Poder Judiciário, garantias e CNJ',source:'Material específico enviado',page:219,
   explanation:'O Judiciário é composto pelos órgãos do art. 92. As garantias da magistratura protegem independência funcional, enquanto as vedações preservam imparcialidade. STF exerce principalmente guarda da Constituição; STJ uniformiza a interpretação da legislação federal. O CNJ controla atuação administrativa e financeira, não substitui a função jurisdicional dos tribunais.',
   points:['STF, CNJ e Tribunais Superiores têm sede na Capital Federal; STF e Superiores possuem jurisdição nacional.','Ingresso na magistratura ocorre no cargo inicial de juiz substituto, com concurso de provas e títulos e três anos de atividade jurídica.','Garantias: vitaliciedade, inamovibilidade e irredutibilidade de subsídio.','Quinto constitucional reserva vagas em determinados tribunais a membros do MP e advogados, conforme requisitos.','CNJ possui funções administrativas, financeiras e disciplinares; não é instância recursal das decisões judiciais.'],
   example:'Uma reclamação disciplinar contra magistrado pode envolver o CNJ; recurso contra sentença segue o sistema judicial competente.',
   bizu:'STF = Constituição; STJ = lei federal; CNJ = controle administrativo/financeiro/disciplinar.',
   mnemonic:'V-I-I: Vitaliciedade, Inamovibilidade, Irredutibilidade.',
   trap:'O CNJ integra o Poder Judiciário, mas não exerce jurisdição como tribunal de recursos.'},
  {id:'cf-forcas',category:'Direito Constitucional',title:'Forças Armadas e militares',source:'Material específico enviado',page:219,
   explanation:'Marinha, Exército e Aeronáutica são instituições nacionais permanentes e regulares, baseadas em hierarquia e disciplina e sob autoridade suprema do Presidente. Destinam-se à defesa da Pátria, garantia dos poderes constitucionais e, por iniciativa de qualquer deles, garantia da lei e da ordem.',
   points:['Lei complementar estabelece normas gerais de organização, preparo e emprego.','Não cabe habeas corpus em relação ao mérito de punições disciplinares militares, sem excluir controle de legalidade reconhecido pelo sistema jurídico.','Militar da ativa não pode sindicalizar-se, fazer greve nem filiar-se a partido político.','Patentes dos oficiais são conferidas pelo Presidente, com prerrogativas, direitos e deveres.','Regras sobre cargo civil, mandato eletivo e perda de posto/patente possuem tratamento constitucional específico.'],
   example:'A questão que atribui iniciativa autônoma às Forças Armadas para garantia da lei e da ordem contraria a fórmula constitucional.',
   bizu:'Memorize estrutura e finalidade em duas tríades: MEA e DPG.',
   mnemonic:'MEA: Marinha, Exército, Aeronáutica. DPG: Defesa da Pátria, Poderes constitucionais, GLO.',
   trap:'As Forças Armadas não são um “poder moderador” e não atuam acima dos Poderes constituídos.'},
  {id:'dh-caracteristicas',category:'Direitos Humanos',title:'Características dos Direitos Humanos',source:'Material específico enviado',page:150,
   explanation:'As características explicam como os Direitos Humanos protegem a dignidade. Eles alcançam todas as pessoas, não podem ser tratados como mercadoria, formam um conjunto integrado e evoluem historicamente. Em prova, os conceitos aparecem por meio de situações concretas.',
   points:['Universalidade: pertencem a todos, sem discriminação.','Inalienabilidade e irrenunciabilidade: não podem ser vendidos nem abandonados validamente.','Indivisibilidade e interdependência: direitos civis, políticos, sociais, econômicos e culturais se complementam.','Historicidade: o catálogo se desenvolve com mudanças e novas necessidades sociais.','Imprescritibilidade refere-se ao núcleo dos Direitos Humanos; não se confunde com imprescritibilidade de toda pretensão patrimonial.'],
   example:'Sem educação, o exercício do trabalho digno e da participação política pode ser prejudicado: isso demonstra interdependência.',
   bizu:'Quando a questão falar “para todos”, pense universalidade; “não pode vender”, inalienabilidade; “um depende do outro”, interdependência.',
   mnemonic:'UNI-INA-IRRE-INDI-INTER-HIST: Universal, Inalienável, Irrenunciável, Indivisível, Interdependente e Histórico.',
   trap:'Universalidade não significa que todos os direitos sejam absolutos ou aplicados sem ponderação.'},
  {id:'dh-dimensoes',category:'Direitos Humanos',title:'Dimensões ou gerações dos Direitos Humanos',source:'Material específico enviado',page:150,
   explanation:'A classificação por dimensões é didática e cumulativa: uma dimensão não elimina a anterior. Primeira dimensão associa-se à liberdade e contenção do Estado; segunda, à igualdade material e prestações estatais; terceira, à solidariedade e interesses coletivos. O conteúdo de quarta e quinta dimensões varia conforme a doutrina.',
   points:['1ª: direitos civis e políticos, liberdades negativas e defesa contra interferências indevidas.','2ª: direitos sociais, econômicos e culturais, com atuação positiva do Estado.','3ª: direitos difusos e coletivos, como paz, meio ambiente e desenvolvimento.','4ª e 5ª não possuem classificação uniforme: democracia, informação, pluralismo, biotecnologia ou paz aparecem conforme o autor.','O termo dimensão é preferido por muitos autores porque evidencia acumulação, não substituição.'],
   example:'Liberdade de expressão é associada à primeira; saúde à segunda; meio ambiente equilibrado à terceira.',
   bizu:'Se a banca não indicar autor, tenha cautela com quarta e quinta dimensões; 1ª, 2ª e 3ª são mais estáveis.',
   mnemonic:'L-I-S: Liberdade, Igualdade, Solidariedade.',
   trap:'Não diga que direitos sociais surgiram para extinguir liberdades individuais; as dimensões convivem.'},
  {id:'dh-dudh',category:'Direitos Humanos',title:'Declaração Universal dos Direitos Humanos',source:'Material específico enviado',page:157,
   explanation:'A DUDH, proclamada em 1948, parte da dignidade e igualdade de todos e reúne direitos civis, políticos, econômicos, sociais e culturais. Seu texto deve ser lido de forma integrada: liberdade vem acompanhada de responsabilidade e respeito aos direitos alheios.',
   points:['Proíbe escravidão, tortura e tratamentos cruéis, desumanos ou degradantes.','Reconhece igualdade perante a lei, recurso efetivo, devido processo e presunção de inocência.','Protege privacidade, circulação, asilo, nacionalidade, família, propriedade, pensamento, religião, expressão e associação.','Reconhece segurança social, trabalho, repouso, padrão de vida adequado, educação e participação cultural.','O exercício dos direitos pode sofrer limitações legais voltadas ao respeito alheio, moral, ordem pública e bem-estar democrático.'],
   example:'Presunção de inocência exige tratamento de não culpado até comprovação segundo processo público com garantias de defesa.',
   bizu:'Agrupe os 30 artigos: dignidade/igualdade; liberdades e garantias; participação; direitos sociais; deveres e limites.',
   mnemonic:'VIDA-LI-IG: Vida, Liberdade, Igualdade — núcleo inicial para lembrar a lógica da Declaração.',
   trap:'A DUDH não contém apenas direitos individuais; também possui amplo bloco de direitos sociais.'},
  {id:'dh-penal',category:'Direitos Humanos',title:'Tratamento penal, dignidade e Regras de Mandela',source:'Material específico enviado',page:150,
   explanation:'A privação de liberdade restringe o direito de ir e vir, não retira a dignidade nem os demais direitos compatíveis com a execução da pena. Estado deve proteger integridade física e moral e fornecer condições de saúde, higiene, educação, trabalho e contato social conforme a lei e parâmetros internacionais.',
   points:['Saúde prisional deve ser prestada sem discriminação e com independência profissional.','Educação e trabalho são instrumentos de desenvolvimento e reintegração, não favores concedidos ao preso.','Separação por categorias considera situação processual, idade, sexo e necessidades de proteção.','Uso da força e instrumentos de contenção são excepcionais, necessários, proporcionais e sujeitos a controle.','Contato com família, acesso à defesa e mecanismos de reclamação reduzem abusos e favorecem reinserção.'],
   example:'A pessoa presa mantém direito a atendimento médico equivalente e não pode sofrer tratamento degradante como forma adicional de punição.',
   bizu:'Em caso prático, pergunte: a restrição decorre da sentença ou é sofrimento extra sem base legal?',
   mnemonic:'S-E-T-F-D: Saúde, Educação, Trabalho, Família e Defesa.',
   trap:'Direitos Humanos não impedem a execução da pena; impedem que ela ultrapasse limites legais e viole a dignidade.'},
  {id:'lei-desarmamento',category:'Legislação Especial',title:'Estatuto do Desarmamento: sistema, registro, posse e porte',source:'Material específico enviado',page:106,
   explanation:'A Lei 10.826/2003 disciplina registro, posse, porte, comércio e crimes envolvendo armas, acessórios e munições. Sinarm, registro e autorização não são sinônimos. Posse refere-se à manutenção nos locais autorizados; porte envolve condução fora desses limites.',
   points:['Sinarm funciona no Ministério da Justiça, no âmbito da Polícia Federal, com circunscrição nacional e funções cadastrais.','Registro autoriza a manutenção da arma nos locais definidos em lei; porte é excepcional e depende de autorização/hipótese legal.','A lei diferencia arma de uso permitido, restrito ou proibido, e também condutas com identificação raspada ou adulterada.','Omissão de cautela, comércio ilegal e tráfico internacional possuem estruturas próprias.','A análise do crime exige observar local, tipo de arma, autorização, condição do agente e verbo praticado.'],
   example:'Manter arma irregular em residência e transportá-la na rua são situações juridicamente diferentes: posse e porte têm tipos e circunstâncias distintos.',
   bizu:'Monte cinco perguntas: quem, qual arma, onde, com autorização e o que fez?',
   mnemonic:'S-R-P-P-C: Sinarm, Registro, Posse, Porte, Crimes.',
   trap:'Registro da arma não equivale automaticamente a autorização para portá-la em qualquer lugar.'},
  {id:'lei-abuso',category:'Legislação Especial',title:'Abuso de Autoridade: estrutura completa da Lei 13.869/2019',source:'Material específico enviado',document:'vade',page:71,
   explanation:'O crime de abuso de autoridade depende de agente público, atuação funcional ou a pretexto dela, conduta tipificada e finalidade específica. A lei não pune mera ilegalidade culposa ou divergência razoável de interpretação. Os crimes são de ação penal pública incondicionada.',
   points:['Agente público é conceito amplo e inclui atuação transitória ou sem remuneração.','Finalidade específica: prejudicar, beneficiar a si/terceiro ou agir por capricho/satisfação pessoal.','Divergência na interpretação da lei ou avaliação de fatos e provas, isoladamente, não configura abuso.','Efeitos como perda do cargo e inabilitação dependem dos requisitos legais e não são automáticos em toda condenação.','Responsabilidades civil, administrativa e penal são independentes, com efeitos recíprocos nas hipóteses legais.'],
   example:'Uma decisão posteriormente reformada não prova abuso. É necessário demonstrar tipo penal e finalidade específica exigida.',
   bizu:'Resolva em quatro filtros: Agente + Função + Tipo + Dolo específico.',
   mnemonic:'PBC: Prejudicar, Beneficiar, Capricho. Sem PBC, desconfie do abuso penal.',
   trap:'Não transforme todo erro funcional em crime; a lei exige elementos objetivos e subjetivos específicos.'},
  {id:'lei-tortura',category:'Legislação Especial',title:'Lei de Tortura: modalidades, consumação e causas relevantes',source:'Material específico enviado',document:'vade',page:78,
   explanation:'A Lei 9.455/1997 tipifica modalidades de tortura conforme conduta, sofrimento e finalidade. Na tortura inquisitorial, crime e discriminação, constranger com violência ou grave ameaça deve causar sofrimento físico ou mental. Não é necessário alcançar o resultado pretendido além do sofrimento típico.',
   points:['Tortura-prova: obter informação, declaração ou confissão. Tortura-crime: provocar ação ou omissão criminosa.','Tortura-discriminação: motivação racial ou religiosa. Tortura-castigo: vítima sob guarda, poder ou autoridade, com intenso sofrimento.','Há figura omissiva para quem tinha dever de evitar ou apurar e se omite.','A condição de agente público pode aumentar a pena; também importam idade/condição da vítima e outras hipóteses legais.','A condenação produz efeitos próprios previstos na lei e o crime recebe tratamento constitucional rigoroso.'],
   example:'Se o agente causa sofrimento para obter confissão, o crime consuma-se com o sofrimento; a confissão efetiva não é necessária.',
   bizu:'Primeiro identifique a finalidade; depois verifique vínculo de guarda/poder e, por fim, se há ação ou omissão.',
   mnemonic:'P-C-D-C-O: Prova, Crime, Discriminação, Castigo, Omissão.',
   trap:'Na modalidade castigo, a lei exige intenso sofrimento e relação de guarda, poder ou autoridade.'},
  {id:'lei-hediondos',category:'Legislação Especial',title:'Crimes hediondos e equiparados',source:'Material específico enviado',document:'vade',page:65,
   explanation:'Hediondez é classificação legal: o crime deve constar do rol da Lei 8.072/1990. O rol alcança crimes consumados ou tentados quando a lei assim prevê. Tortura, tráfico ilícito de drogas e terrorismo são equiparados por tratamento constitucional e legal, não integrantes do rol pelo mesmo fundamento técnico.',
   points:['Homicídio qualificado e homicídio em atividade típica de grupo de extermínio figuram no rol; homicídio simples, em regra, não.','Roubo e extorsão somente são hediondos nas formas expressamente listadas.','Estupro e estupro de vulnerável recebem classificação legal, inclusive formas qualificadas.','O rol sofre alterações legislativas; deve-se conferir a versão vigente para novos tipos e requisitos.','Consequências sobre fiança, graça, anistia, indulto e execução devem ser estudadas de acordo com a legislação atual.'],
   example:'Um delito ser muito grave não basta. Se a forma específica não estiver no rol legal, não pode ser chamada de hedionda apenas por interpretação extensiva.',
   bizu:'Estude o rol em famílias: vida/integridade; patrimônio; dignidade sexual; saúde pública; vulneráveis/Estado.',
   mnemonic:'3T equiparados: Tortura, Tráfico e Terrorismo.',
   trap:'Não confunda crime hediondo com crime equiparado a hediondo; o tratamento aproxima, mas a classificação técnica difere.'},
  {id:'lei-racismo',category:'Legislação Especial',title:'Crimes de racismo e discriminação (Lei 7.716/1989)',source:'Material específico enviado',document:'vade',page:68,
   explanation:'A lei pune discriminação ou preconceito por raça, cor, etnia, religião ou procedência nacional e descreve condutas em emprego, serviço público, comércio, ensino, hospedagem, transporte e outros espaços. Também contempla injúria racial no texto legal atual do material.',
   points:['A análise começa pela motivação discriminatória e pelo verbo: impedir, obstar, negar, recusar, induzir, incitar ou ofender.','Impedir acesso a cargo, negar emprego ou tratar trabalhador de forma desigual pode configurar os tipos previstos.','Recusar atendimento em estabelecimento por razão discriminatória possui tipo específico.','Induzir ou incitar discriminação alcança divulgação pública e pode possuir causas de aumento conforme o meio.','A Constituição trata o racismo como inafiançável e imprescritível.'],
   example:'Negar emprego por falta de qualificação não é racismo; negar por raça ou etnia pode preencher o tipo, se presentes os demais elementos.',
   bizu:'Resolva pelo trio M-V-A: Motivação, Verbo e Ambiente em que ocorreu.',
   mnemonic:'R-C-E-R-P: Raça, Cor, Etnia, Religião, Procedência nacional.',
   trap:'Não conclua pela aparência do conflito: é preciso vínculo entre a conduta e o fator discriminatório protegido.'},
  {id:'pmpe-ingresso',category:'Legislação Institucional',title:'Estatuto da PMPE: ingresso, carreira e situação jurídica',source:'Estatuto da PMPE enviado',page:175,
   explanation:'A Lei estadual nº 6.783/1974 regula situação, obrigações, deveres, direitos e prerrogativas dos policiais militares de Pernambuco. O serviço policial-militar corresponde às atividades próprias da corporação; a carreira é continuada e privativa de pessoal da ativa, observadas as regras legais.',
   points:['A PMPE é instituição permanente, força auxiliar e reserva do Exército, subordinada ao Governador nos termos constitucionais e legais.','Ingresso depende dos requisitos legais e matrícula em estabelecimento de ensino policial-militar.','A condição jurídica resulta da Constituição, Estatuto, leis e regulamentos próprios.','Ativa, reserva remunerada e reforma possuem efeitos diferentes sobre vínculo e disponibilidade.','Cargo é conjunto de atribuições; função é o exercício das obrigações inerentes ao cargo.'],
   example:'Cargo e função não são idênticos: o cargo é a posição prevista na organização; a função é o exercício concreto das obrigações.',
   bizu:'Ao estudar o Estatuto, sempre separe situação do militar, cargo ocupado e função efetivamente exercida.',
   mnemonic:'S-C-F: Situação, Cargo, Função.',
   trap:'Não aplique automaticamente ao policial militar todas as regras do servidor civil; existe regime constitucional e estatutário próprio.'},
  {id:'pmpe-hierarquia',category:'Legislação Institucional',title:'Estatuto da PMPE: hierarquia, disciplina e precedência',source:'Estatuto da PMPE enviado',page:175,
   explanation:'Hierarquia e disciplina são bases institucionais. Hierarquia organiza a autoridade em níveis; disciplina é rigorosa observância e acatamento das leis, regulamentos, normas e ordens que sustentam o funcionamento regular da corporação.',
   points:['Posto é o grau hierárquico do oficial; graduação é o grau da praça.','Círculos hierárquicos são âmbitos de convivência entre policiais da mesma categoria, voltados à camaradagem sem prejuízo do respeito.','A precedência considera grau hierárquico e critérios legais de antiguidade.','Subordinação decorre da estrutura e não afeta a dignidade pessoal do policial militar.','Alunos-oficiais, aspirantes e praças especiais possuem posição definida na escala e regras próprias de precedência.'],
   example:'Dois militares da mesma graduação podem ter precedência definida por antiguidade conforme critérios estatutários.',
   bizu:'Não misture: posto = oficial; graduação = praça; círculo = convivência; precedência = quem vem antes.',
   mnemonic:'PO-GRA-CI-PRE: Posto, Graduação, Círculo, Precedência.',
   trap:'Hierarquia não autoriza ordem manifestamente ilegal nem elimina a responsabilidade individual.'},
  {id:'pmpe-etica',category:'Legislação Institucional',title:'Estatuto da PMPE: valor, ética e deveres',source:'Estatuto da PMPE enviado',page:175,
   explanation:'O valor policial-militar reúne manifestações essenciais da identidade profissional. Ética, sentimento do dever, pundonor e decoro orientam conduta pública e privada. Os deveres nascem de vínculos racionais e morais com a comunidade, a corporação e o serviço.',
   points:['Patriotismo, civismo, fé na missão, espírito de corpo, amor à profissão e aprimoramento técnico integram o valor militar.','Probidade, lealdade, justiça, responsabilidade e respeito à dignidade são referências éticas.','O compromisso solene traduz aceitação consciente das obrigações profissionais.','Comando reúne autoridade, deveres e responsabilidades; quanto maior a autoridade, maior a responsabilidade.','Cabos e soldados são essencialmente elementos de execução; subtenentes e sargentos auxiliam e complementam atividades dos oficiais.'],
   example:'Uma conduta pode atingir decoro e pundonor mesmo fora do serviço quando compromete a dignidade da função e a imagem institucional, conforme o regime aplicável.',
   bizu:'Em questão de ética, procure o valor protegido: missão, honestidade, lealdade, dignidade, responsabilidade ou espírito de corpo.',
   mnemonic:'FÉ-PALE: Fé na missão, Espírito de corpo, Patriotismo, Amor à profissão, Lealdade, Evolução técnica.',
   trap:'Espírito de corpo não significa acobertar ilegalidade; deve coexistir com legalidade, verdade e responsabilidade.'},
  {id:'pmpe-responsabilidade',category:'Legislação Institucional',title:'Estatuto da PMPE: responsabilidade e violações',source:'Estatuto da PMPE enviado',page:175,
   explanation:'O policial militar responde integralmente pelas decisões e atos praticados. Violação de obrigação ou dever pode gerar responsabilidade disciplinar, administrativa, civil ou penal, de acordo com natureza e gravidade. As instâncias não devem ser confundidas.',
   points:['A violação pode constituir crime, contravenção ou transgressão disciplinar.','Responsabilidade cresce com o grau hierárquico e a autoridade exercida.','Manifestações coletivas sobre atos de superiores ou questões político-partidárias sofrem restrições estatutárias.','Procedimentos de conselho e competência judicial observam hipóteses próprias para oficiais, aspirantes e praças estáveis.','Regulamento Disciplinar especifica e classifica transgressões e disciplina aplicação das sanções.'],
   example:'O mesmo fato pode ser apurado em esferas distintas, mas cada consequência depende de seu fundamento e procedimento.',
   bizu:'Em caso prático, classifique a esfera: disciplinar, civil ou penal; depois procure autoridade e rito competente.',
   mnemonic:'D-C-P: Disciplinar, Civil, Penal.',
   trap:'Sanção disciplinar não elimina automaticamente eventual responsabilidade civil ou penal.'},
  {id:'pmpe-direitos',category:'Legislação Institucional',title:'Estatuto da PMPE: direitos, férias, licenças e prerrogativas',source:'Estatuto da PMPE enviado',page:175,
   explanation:'Os direitos estatutários abrangem remuneração, promoção, estabilidade nas condições legais, férias, afastamentos, licenças, assistência e prerrogativas. Cada instituto possui requisitos, prazo, autoridade e efeitos próprios sobre serviço e carreira.',
   points:['Promoção segue critérios e legislação específica, com acesso seletivo, gradual e sucessivo.','Férias são afastamento anual e obrigatório; outros afastamentos possuem fundamentos próprios.','Licença é autorização de afastamento total e pode assumir modalidades previstas no Estatuto.','Prerrogativas decorrem do cargo, grau hierárquico e função, não são privilégios pessoais desvinculados do serviço.','Prisão de policial militar observa garantias e hipóteses estatutárias específicas, sem afastar a legalidade.'],
   example:'Férias, licença especial e licença para interesse particular não produzem necessariamente os mesmos efeitos na contagem de tempo e remuneração.',
   bizu:'Monte quadro com instituto, requisito, duração, remuneração, contagem de tempo e quem autoriza.',
   mnemonic:'RRFLP: Remuneração, Recurso, Férias, Licenças, Prerrogativas.',
   trap:'Direito ou prerrogativa funcional não pode ser interpretado como autorização para descumprir dever legal.'}
];

